function voiceGlyph(name){const paths={people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87',share:'M12 16V3m-5 5 5-5 5 5M5 12H3v9h18v-9h-2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',leave:'M9 3H3v18h6m5-14 5 5-5 5M7 12h12',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M18 6 6 18',muted:'m3 3 18 18M9 9v3a3 3 0 0 0 5 2M15 9V5a3 3 0 0 0-6 0M5 11v1a7 7 0 0 0 12 5M19 11v1M12 19v3m-4 0h8'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${name==='people'?'<circle cx="9" cy="7" r="4"/>':''}<path d="${paths[name]||paths.plus}"/></svg>`;}
function voiceRoomHTML(id){
 const close='<button type="button" class="voice-dialog-close" data-voice="dismiss" aria-label="닫기">'+voiceGlyph('close')+'</button>';
 return `<section class="voice-room" data-voice-room="${esc(id)}"><header class="voice-heading"><a href="#voice">← 토킹룸</a><button class="small-button voice-leave" data-voice="leave">${voiceGlyph('leave')} 나가기</button><h1 id="voice-title">토킹룸</h1><p><span id="voice-count"></span><span id="voice-status" role="status">연결하는 중…</span></p></header><div id="voice-entry" hidden><button id="voice-join" class="primary-button">다시 연결</button></div><div id="voice-content" hidden><div class="voice-columns"><section class="voice-stage"><div class="voice-stage-toolbar"><p>좌석을 눌러 참여 신청해보세요.</p><div><button type="button" class="voice-icon-button" data-voice="participants" aria-label="참가자 목록">${voiceGlyph('people')}<span id="voice-people-count"></span></button><button type="button" class="voice-icon-button" data-voice="sound" aria-label="소리 설정">${icon('volume')}</button><button type="button" class="voice-icon-button" data-voice="settings" aria-label="방 설정">${voiceGlyph('settings')}</button><button type="button" class="voice-icon-button" data-voice="share" aria-label="초대하기">${voiceGlyph('share')}</button></div></div><div id="voice-seats" class="voice-seats"></div><div id="voice-music-player" class="voice-music-mini" aria-label="공동 음악"></div><button class="small-button voice-unlock-audio" data-voice="resume-audio" hidden>소리 켜기</button><button class="small-button voice-cancel-request" data-voice="cancel-mic" hidden>신청 취소</button><p id="voice-mic-note" class="quiet"></p><div class="voice-listener-heading"><h2>함께 듣는 사람 <span id="voice-listener-count"></span></h2><button type="button" data-voice="participants">전체 보기 ›</button></div><div id="voice-listeners" class="voice-listeners"></div></section><section class="voice-chat-panel"><header><h2>실시간 대화</h2><button type="button" data-voice="participants" aria-label="접속자 목록">${voiceGlyph('people')}<span id="voice-chat-count"></span></button></header><div id="voice-chat" class="voice-chat" aria-live="polite" aria-relevant="additions"></div><form id="voice-chat-form"><label class="sr-only" for="voice-message">메시지</label><input id="voice-message" name="body" placeholder="함께 이야기해요…" maxlength="500" required autocomplete="off"><button type="button" class="voice-icon-button" data-voice="gift" aria-label="선물 보내기">${icon('gift')}</button><button class="primary-button" aria-label="메시지 전송">${voiceGlyph('share')}</button></form></section></div><div id="voice-gift-animation" class="voice-gift-animation" role="status" hidden></div>
 <dialog id="voice-sound" class="voice-sheet">${close}<h2>소리 설정</h2><p id="voice-sound-current" class="quiet"></p><section id="voice-host-audio"><h3>방 전체 음악</h3><div class="voice-sound-controls"><button data-voice="music-play">재생</button><button data-voice="music-pause">일시정지</button><button data-voice="music-next">다음 곡</button><button data-voice="music-stop">종료</button></div><label>음악 볼륨 <input id="voice-room-volume" type="range" min="0" max="100" step="1"></label><label>목소리 중심 ↔ 음악 중심 <input id="voice-balance" type="range" min="0" max="100" step="1"></label><button class="small-button" data-voice="music-picker">음악 검색 · 대기열</button></section><h3>내가 듣는 소리</h3><label>음악 볼륨 <input id="voice-music-volume" type="range" min="0" max="100" step="1" value="100"></label><label>참가자 목소리 <input id="voice-listen-volume" type="range" min="0" max="100" step="1" value="100"></label><label>내 마이크 입력 장치 <select id="voice-input"><option value="">기본 마이크</option></select></label><label>내 마이크 음량 <input id="voice-input-gain" type="range" min="0" max="100" step="1" value="100"></label><label>마이크 음질 <select id="voice-preset"><option value="original">원음</option><option value="radio" selected>라디오 클린</option><option value="studio">스튜디오</option></select></label><label><input id="voice-noise" type="checkbox" checked> 잡음 감소</label><label>리버브 강도 <input id="voice-reverb" type="range" min="0" max="7" step="1" value="0"></label><label>출력 장치 <select id="voice-output"><option value="">기본 스피커 / 이어폰</option></select></label><label><input type="checkbox" id="voice-monitor"> 내 목소리 모니터링 (이어폰 권장)</label><p class="quiet">블루투스 출력은 기기 설정에서 선택해주세요. 장치가 지원하지 않는 효과는 원음으로 연결돼요.</p></dialog>
 <dialog id="voice-members" class="voice-sheet">${close}<h2>참가자</h2><div id="voice-members-list"></div><div id="voice-member-tools"></div></dialog>
 <dialog id="voice-room-settings" class="voice-sheet">${close}<h2>방 설정</h2><section id="voice-requests"></section><button class="small-button" data-voice="close" hidden>토킹룸 종료</button></dialog>
 <dialog id="voice-music-sheet" class="voice-sheet">${close}<h2>함께 듣는 음악</h2><form id="voice-music-search"><label class="sr-only" for="voice-music-query">곡명 · 아티스트</label><input id="voice-music-query" placeholder="곡명 · 아티스트 검색" maxlength="100"><button class="small-button">검색</button></form><p class="quiet">권리자가 공동 감상을 허용한 원곡만 재생할 수 있어요.</p><div id="voice-music-results"></div><div class="voice-music-transport"><button data-voice="music-play">재생</button><button data-voice="music-pause">일시정지</button><button data-voice="music-next">다음 곡</button><button data-voice="music-stop">종료</button><label>재생 위치 <input id="voice-music-seek" type="range" min="0" max="0" value="0" step="1"></label></div><h3>재생목록</h3><div id="voice-music-queue"></div></dialog>
 <dialog id="voice-invite-sheet" class="voice-sheet">${close}<h2>초대하기</h2><button class="small-button" data-voice="copy-link">초대 링크 복사</button><form id="voice-invite-form"><label>대화한 친구 <select name="profile_id" required id="voice-contacts"><option value="">친구 선택</option></select></label><button class="small-button">초대 DM 보내기</button><p class="quiet">비공개방 초대는 방장·관리자만 보낼 수 있어요.</p></form></dialog>
 <dialog id="voice-gift-sheet" class="voice-sheet">${close}<h2>선물 보내기</h2><form id="voice-gift-form"><label>받는 사람 <select name="profile_id" required id="voice-gift-target"></select></label><label>선물 <select name="gift_type">${AifectGifts.GIFT_CATALOG.map(g=>`<option value="${esc(g.id)}">${esc(g.name)} · ${number(g.gold)} G</option>`).join('')}</select></label><label>수량 <input name="quantity" type="number" min="1" max="100" value="1" required></label><p id="voice-gift-summary"></p><button class="primary-button">골드 선물 보내기</button><p class="quiet">기존 프로필 선물 정산 기준이 적용돼요.</p><p id="voice-gift-result" role="status"></p></form></dialog></div></section>`;
}
